"""Compile parsed policy rules into a canonical live-state image.

The image is the minimal deterministic complete language machine over the
registered service alphabet with its dead residual removed and the retained
residuals numbered by breadth-first discovery from START in increasing label
order.  Construction: prefix trie for match atoms, small KMP-style automata for
the other atoms, lazy product search, bitset formula evaluation, dead-residual
elimination and Moore partition refinement.
"""

from syntax import PolicyError

DENY = 4294967295


def _kmp_prefix(path):
    pi = [0] * len(path)
    for i in range(1, len(path)):
        j = pi[i - 1]
        while j > 0 and path[i] != path[j]:
            j = pi[j - 1]
        if path[i] == path[j]:
            j += 1
        pi[i] = j
    return pi


def _kmp_step(path, pi, j, c):
    n = len(path)
    while j > 0 and (j == n or path[j] != c):
        j = pi[j - 1]
    if j < n and path[j] == c:
        return j + 1
    return 0


def _atom_automaton(kind, path, ncols):
    """Return (trans, accept_set) for one non-match atom over column indices."""
    n = len(path)
    if kind == 'startswith':
        dead = n + 1
        trans = []
        for j in range(n + 2):
            row = []
            for c in range(ncols):
                if j < n:
                    row.append(j + 1 if c == path[j] else dead)
                elif j == n:
                    row.append(n)
                else:
                    row.append(dead)
            trans.append(row)
        return trans, frozenset((n,))
    if kind == 'endswith':
        pi = _kmp_prefix(path)
        trans = [[_kmp_step(path, pi, j, c) for c in range(ncols)] for j in range(n + 1)]
        return trans, frozenset((n,))
    # contains: KMP with absorbing match state
    pi = _kmp_prefix(path)
    trans = [[_kmp_step(path, pi, j, c) for c in range(ncols)] for j in range(n + 1)]
    trans[n] = [n] * ncols
    return trans, frozenset((n,))


def compile_image(rules, name_to_col, ncols):
    """Build the image dict {'accept': [...], 'rows': [[...], ...]} plus cells.

    Raises PolicyError for unregistered names (replay-stage rejection).
    """

    def cols(path):
        try:
            return tuple(name_to_col[x] for x in path)
        except KeyError:
            raise PolicyError('registry')

    match_ids = {}
    match_paths = []
    nm_ids = {}
    nm_atoms = []
    simple_allow = set()
    simple_drop = set()
    complex_rules = []

    def mpid(pc):
        i = match_ids.get(pc)
        if i is None:
            i = len(match_paths)
            match_ids[pc] = i
            match_paths.append(pc)
        return i

    def nnid(kind, pc):
        key = (kind, pc)
        i = nm_ids.get(key)
        if i is None:
            i = len(nm_atoms)
            nm_ids[key] = i
            nm_atoms.append((kind, pc))
        return i

    def conv(node):
        kind = node[0]
        if kind == 'match':
            return ('M', mpid(cols(node[1])))
        if kind in ('startswith', 'endswith', 'contains'):
            return ('N', nnid(kind, cols(node[1])))
        if kind == 'not':
            return ('n', conv(node[1]))
        return (kind, conv(node[1]), conv(node[2]))

    for pred, action in rules:
        if pred[0] == 'match':
            pid = mpid(cols(pred[1]))
            (simple_allow if action == 'allow' else simple_drop).add(pid)
        else:
            complex_rules.append((action, conv(pred)))

    # ---- prefix trie of all match paths ----
    children = [{}]
    term_node = [None] * len(match_paths)
    for pid, path in enumerate(match_paths):
        node = 0
        for c in path:
            nxt = children[node].get(c)
            if nxt is None:
                nxt = len(children)
                children[node][c] = nxt
                children.append({})
            node = nxt
        term_node[pid] = node

    # ---- non-match atom automata ----
    nm_trans = []
    nm_accept = []
    for kind, path in nm_atoms:
        t, a = _atom_automaton(kind, path, ncols)
        nm_trans.append(t)
        nm_accept.append(a)
    nnm = len(nm_atoms)

    # ---- lazy product BFS over (trie node or dead, non-match state tuple) ----
    nm_start = tuple(0 for _ in range(nnm))
    state_node = [0]
    state_nm = [nm_start]
    lookup = {(0, nm_start): 0}
    state_trans = []
    i = 0
    while i < len(state_node):
        node = state_node[i]
        nm = state_nm[i]
        row = [0] * ncols
        for c in range(ncols):
            nnode = children[node].get(c, -1) if node >= 0 else -1
            if nnm:
                ntuple = tuple(nm_trans[k][nm[k]][c] for k in range(nnm))
            else:
                ntuple = nm_start
            key = (nnode, ntuple)
            j = lookup.get(key)
            if j is None:
                j = len(state_node)
                lookup[key] = j
                state_node.append(nnode)
                state_nm.append(ntuple)
            row[c] = j
        state_trans.append(row)
        i += 1
    ns = len(state_node)

    # ---- acceptance via bitset evaluation of the rule formula ----
    allow_nodes = set()
    drop_nodes = set()
    for pid in simple_allow:
        allow_nodes.add(term_node[pid])
    for pid in simple_drop:
        drop_nodes.add(term_node[pid])

    used_match = set()
    used_nm = set()

    def gather(node):
        kind = node[0]
        if kind == 'M':
            used_match.add(node[1])
        elif kind == 'N':
            used_nm.add(node[1])
        elif kind == 'n':
            gather(node[1])
        else:
            gather(node[1])
            gather(node[2])

    for _action, tree in complex_rules:
        gather(tree)

    masks = {}
    node_match = {}
    for pid in used_match:
        masks[('M', pid)] = bytearray(ns)
        node_match.setdefault(term_node[pid], []).append(pid)
    for nid in used_nm:
        masks[('N', nid)] = bytearray(ns)
    if used_nm:
        for i in range(ns):
            nm = state_nm[i]
            for nid in used_nm:
                if nm[nid] in nm_accept[nid]:
                    masks[('N', nid)][i] = 1
    if used_match:
        for i in range(ns):
            pids = node_match.get(state_node[i])
            if pids:
                for pid in pids:
                    masks[('M', pid)][i] = 1
    mask_int = {k: int.from_bytes(v, 'little') for k, v in masks.items()}
    ALL = (1 << ns) - 1

    def evaluate(node):
        kind = node[0]
        if kind in ('M', 'N'):
            return mask_int[node]
        if kind == 'n':
            return ALL ^ evaluate(node[1])
        if kind == 'and':
            return evaluate(node[1]) & evaluate(node[2])
        return evaluate(node[1]) | evaluate(node[2])

    complex_allow = 0
    complex_drop = 0
    for action, tree in complex_rules:
        if action == 'allow':
            complex_allow |= evaluate(tree)
        else:
            complex_drop |= evaluate(tree)

    accept = bytearray(ns)
    for i in range(ns):
        node = state_node[i]
        ok = node in allow_nodes or ((complex_allow >> i) & 1)
        bad = node in drop_nodes or ((complex_drop >> i) & 1)
        if ok and not bad:
            accept[i] = 1

    def empty_image():
        row = [DENY] * ncols
        return {'accept': [False], 'rows': [row]}, 0

    if not any(accept):
        return empty_image()

    # ---- live states: can reach an accepting state ----
    rev = [[] for _ in range(ns)]
    for i in range(ns):
        row = state_trans[i]
        for c in range(ncols):
            rev[row[c]].append(i)
    live = bytearray(ns)
    stack = [i for i in range(ns) if accept[i]]
    for i in stack:
        live[i] = 1
    while stack:
        j = stack.pop()
        for p in rev[j]:
            if not live[p]:
                live[p] = 1
                stack.append(p)

    live_list = [i for i in range(ns) if live[i]]
    live_index = {}
    for new, old in enumerate(live_list):
        live_index[old] = new
    L = len(live_list)

    # ---- Moore partition refinement on live states + dead sink class ----
    class_of = [1 if accept[old] else 0 for old in live_list]
    nclass = max(class_of) + 1
    while True:
        sig_map = {}
        new_class = [0] * L
        for new in range(L):
            old = live_list[new]
            row = state_trans[old]
            tgt = []
            for c in range(ncols):
                tn = live_index.get(row[c], -1)
                tgt.append(class_of[tn] if tn >= 0 else -1)
            sig = (class_of[new], tuple(tgt))
            cid = sig_map.get(sig)
            if cid is None:
                cid = len(sig_map)
                sig_map[sig] = cid
            new_class[new] = cid
        if len(sig_map) == nclass:
            break
        class_of = new_class
        nclass = len(sig_map)

    class_rep = [0] * nclass
    for new in range(L):
        class_rep[class_of[new]] = live_list[new]

    # ---- BFS numbering of the retained classes from START ----
    start_cls = class_of[live_index[0]]
    order = [start_cls]
    idx = {start_cls: 0}
    head = 0
    while head < len(order):
        c = order[head]
        head += 1
        row = state_trans[class_rep[c]]
        for col in range(ncols):
            tn = live_index.get(row[col], -1)
            if tn < 0:
                continue
            tc = class_of[tn]
            if tc not in idx:
                idx[tc] = len(order)
                order.append(tc)

    rows = []
    accept_out = []
    for c in order:
        row = state_trans[class_rep[c]]
        out_row = []
        for col in range(ncols):
            tn = live_index.get(row[col], -1)
            if tn < 0:
                out_row.append(DENY)
            else:
                tc = class_of[tn]
                out_row.append(idx[tc] if tc in idx else DENY)
        rows.append(out_row)
        accept_out.append(bool(accept[class_rep[c]]))

    cells = sum(1 for row in rows for t in row if t != DENY)
    if len(rows) > 8192:
        raise PolicyError('rows')
    return {'accept': accept_out, 'rows': rows}, cells
